// Production Design System — Android / Kotlin build (ADR 0013, 0017, 0018).
// :tokens is com.pds.tokens, generated by `npm run tokens:build`
// (packages/tokens/scripts/emit-kotlin.mjs) and committed — plain Kotlin/JVM.
// :compose is com.pds.compose, the Jetpack Compose components (Android library).
// Versions: gradle/libs.versions.toml. Build: ./gradlew build (from platforms/android).
pluginManagement {
    repositories {
        google()
        gradlePluginPortal()
        mavenCentral()
    }
}

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "pds-android"

include(":tokens")
include(":compose")
